// Multimap stores elements as nodes in an R-B Tree
// Node structure holds std::pair<const Key, T>
using MM = std::multimap<int, std::string>;
MM m;

// Insertion/Lookup is O(log N). Duplicate keys allowed.
m.emplace(10, "Alpha");
m.emplace(10, "Beta");

// Iterators provide sorted, in-order traversal of the RBT
auto it = m.find(10); 

// Dereferencing yields pair<const int, string>&
const auto& pair_ref = *it;

// Iterator member access via operator->
int key = it->first;         // Key access (guaranteed sorted)
it->second = "New Value";    // Value is mutable

// Key immutability prevents structural damage:
// it->first = 5; // COMPILE ERROR: Key is const
